package com.fathom.account;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc class AccountControllerIntegrationTest { @Autowired MockMvc mockMvc;
@Test void createAndList() throws Exception { var user=mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"U\",\"email\":\"u@a.com\",\"status\":\"ACTIVE\"}" )).andReturn().getResponse().getContentAsString(); String userId=user.split("\"id\":\"")[1].split("\"")[0]; mockMvc.perform(post("/api/users/"+userId+"/accounts").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"HDFC\",\"accountType\":\"BANK_ACCOUNT\"}" )).andExpect(status().isOk()); mockMvc.perform(get("/api/users/"+userId+"/accounts")).andExpect(status().isOk()).andExpect(jsonPath("$[0].name").value("HDFC")); }}
